package com.barrowscryptkilltracker;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Barrows Crypt Kill Tracker", description = "Tracks observed non-brother kills by enemy type in Barrows", tags = {"barrows", "crypt", "kills"})
public class BarrowsCryptKillTrackerPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private OverlayManager overlayManager;
	@Inject private CryptKillOverlay overlay;
	private final CryptKillCounts counts = new CryptKillCounts();
	private volatile boolean active;

	@Override
	protected void startUp()
	{
		active = true;
		overlayManager.add(overlay);
		clientThread.invokeLater(() -> { if (active) { samplePotential(); } });
	}

	@Override
	protected void shutDown()
	{
		active = false;
		overlayManager.remove(overlay);
		clientThread.invoke(counts::clearSession);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN && event.getActor() instanceof NPC && event.getHitsplat().isMine() && event.getHitsplat().getAmount() > 0)
		{
			NPC npc = (NPC) event.getActor();
			if (CryptEnemy.forNpc(npc.getId()) == null) { return; }
			samplePotential();
			counts.damage(npc, npc.getId(), region(npc));
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (active && client.getGameState() == GameState.LOGGED_IN && event.getActor() instanceof NPC)
		{
			NPC npc = (NPC) event.getActor();
			if (CryptEnemy.forNpc(npc.getId()) == null) { return; }
			samplePotential();
			counts.death(npc, region(npc));
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		// Despawn alone is not a kill: scene changes must not inflate counts.
		if (active) { counts.despawn(event.getNpc()); }
	}

	@Subscribe
	public void onGameTick(GameTick event) { samplePotential(); }

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!active) { return; }
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			counts.clearSession();
		}
		else if (event.getGameState() != GameState.LOGGED_IN)
		{
			counts.clearActors();
		}
	}

	private void samplePotential()
	{
		if (active && client.getGameState() == GameState.LOGGED_IN)
		{
			counts.potential(client.getVarbitValue(VarbitID.BARROWS_KILLED_MONSTER));
		}
	}

	private int region(NPC npc)
	{
		WorldView view = npc.getWorldView();
		LocalPoint location = npc.getLocalLocation();
		Scene scene = view == null ? null : view.getScene();
		return scene == null || location == null ? -1
			: WorldPoint.fromLocalInstance(scene, location, view.getPlane()).getRegionID();
	}

	boolean inLowerCrypt()
	{
		if (client.getGameState() != GameState.LOGGED_IN) { return false; }
		WorldView view = client.getTopLevelWorldView();
		Player player = client.getLocalPlayer();
		Scene scene = view == null ? null : view.getScene();
		LocalPoint location = player == null ? null : player.getLocalLocation();
		// Brother tombs occupy plane 3 of the underground region; the lower maze is on plane 0.
		// Use the live scene plane, not a template plane that may differ in an instance.
		return scene != null && location != null && view.getPlane() == 0
			&& WorldPoint.fromLocalInstance(scene, location, view.getPlane()).getRegionID() == CryptKillCounts.CRYPT_REGION;
	}

	CryptKillCounts counts() { return counts; }

	void resetCounts()
	{
		clientThread.invoke(() -> { if (active) { counts.resetCounts(); } });
	}
}

package com.barrowscryptkilltracker;

import net.runelite.api.gameval.NpcID;

enum CryptEnemy
{
	SKELETON("Skeletons"), BLOODWORM("Bloodworms"), RAT("Rats"), GIANT_RAT("Giant rats"),
	SPIDER("Spiders"), GIANT_SPIDER("Giant spiders");

	final String label;

	CryptEnemy(String label) { this.label = label; }

	static CryptEnemy forNpc(int id)
	{
		switch (id)
		{
			case NpcID.BARROWS_SKELETON_UNARMED:
			case NpcID.BARROWS_SKELETON_UNARMED2:
			case NpcID.BARROWS_SKELETON_ARMED:
			case NpcID.BARROWS_SKELETON_ARMED2: return SKELETON;
			case NpcID.BARROWS_BLOODWORM: return BLOODWORM;
			case NpcID.BARROWS_RAT: return RAT;
			case NpcID.BARROWS_GIANTRAT:
			case NpcID.BARROWS_GIANTRAT2:
			case NpcID.BARROWS_GIANTRAT3: return GIANT_RAT;
			case NpcID.BARROWS_SPIDER: return SPIDER;
			case NpcID.BARROWS_GIANTSPIDER: return GIANT_SPIDER;
			default: return null; // Explicit allowlist excludes every brother and unrelated NPC.
		}
	}
}

package com.barrowscryptkilltracker;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Set;
import java.util.IdentityHashMap;
import java.util.Map;

/** Session-local observations, keyed by NPC identity rather than reusable NPC index. */
final class CryptKillCounts
{
	static final int CRYPT_REGION = 14231;
	private final Map<CryptEnemy, Integer> counts = new EnumMap<>(CryptEnemy.class);
	private final Map<Object, CryptEnemy> damaged = new IdentityHashMap<>();
	private final Set<Object> dead = Collections.newSetFromMap(new IdentityHashMap<>());
	private final Set<Object> counted = Collections.newSetFromMap(new IdentityHashMap<>());
	private int previousPotential = -1;

	void damage(Object npc, int npcId, int region)
	{
		CryptEnemy enemy = CryptEnemy.forNpc(npcId);
		if (region == CRYPT_REGION && enemy != null && !counted.contains(npc))
		{
			damaged.put(npc, enemy);
			countDeath(npc); // A fatal hitsplat may arrive after the death notification.
		}
	}

	boolean death(Object npc, int region)
	{
		if (region != CRYPT_REGION) { despawn(npc); return false; }
		dead.add(npc);
		return countDeath(npc);
	}

	private boolean countDeath(Object npc)
	{
		CryptEnemy enemy = damaged.get(npc);
		if (!dead.contains(npc) || enemy == null || !counted.add(npc)) { return false; }
		damaged.remove(npc);
		counts.merge(enemy, 1, Integer::sum);
		return true;
	}

	void despawn(Object npc) { damaged.remove(npc); dead.remove(npc); counted.remove(npc); }
	void clearActors() { damaged.clear(); dead.clear(); counted.clear(); }
	int count(CryptEnemy enemy) { return counts.getOrDefault(enemy, 0); }
	int total() { return counts.values().stream().mapToInt(Integer::intValue).sum(); }

	void potential(int value)
	{
		// Monster reward potential only increases within a run. A decrease marks a reset.
		if (previousPotential >= 0 && value < previousPotential) { resetCounts(); }
		previousPotential = value;
	}

	void resetCounts()
	{
		counts.clear();
		clearActors();
	}

	void clearSession()
	{
		resetCounts();
		previousPotential = -1;
	}
}

package com.barrowscryptkilltracker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

class CryptKillOverlay extends OverlayPanel
{
	private final Client client;
	private final BarrowsCryptKillTrackerPlugin plugin;

	@Inject
	CryptKillOverlay(Client client, BarrowsCryptKillTrackerPlugin plugin)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_LOW);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset", "Crypt kill counts", e -> plugin.resetCounts());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN || !plugin.inLowerCrypt() || plugin.counts().total() == 0) { return null; }
		for (CryptEnemy enemy : CryptEnemy.values())
		{
			int kills = plugin.counts().count(enemy);
			if (kills > 0)
			{
				panelComponent.getChildren().add(LineComponent.builder().left(enemy.label).right(Integer.toString(kills)).build());
			}
		}
		return super.render(graphics);
	}
}

