package com.barrowscryptkilltracker;

import net.runelite.api.gameval.NpcID;
import org.junit.Test;
import static org.junit.Assert.*;

public class CryptKillCountsTest
{
	private static final int REGION = CryptKillCounts.CRYPT_REGION;

	@Test
	public void groupsEveryCryptEnemyVariant()
	{
		int[] skeletons = {NpcID.BARROWS_SKELETON_UNARMED, NpcID.BARROWS_SKELETON_UNARMED2, NpcID.BARROWS_SKELETON_ARMED, NpcID.BARROWS_SKELETON_ARMED2};
		for (int id : skeletons) { assertEquals(CryptEnemy.SKELETON, CryptEnemy.forNpc(id)); }
		int[] rats = {NpcID.BARROWS_GIANTRAT, NpcID.BARROWS_GIANTRAT2, NpcID.BARROWS_GIANTRAT3};
		for (int id : rats) { assertEquals(CryptEnemy.GIANT_RAT, CryptEnemy.forNpc(id)); }
		assertEquals(CryptEnemy.BLOODWORM, CryptEnemy.forNpc(NpcID.BARROWS_BLOODWORM));
		assertEquals(CryptEnemy.RAT, CryptEnemy.forNpc(NpcID.BARROWS_RAT));
		assertEquals(CryptEnemy.SPIDER, CryptEnemy.forNpc(NpcID.BARROWS_SPIDER));
		assertEquals(CryptEnemy.GIANT_SPIDER, CryptEnemy.forNpc(NpcID.BARROWS_GIANTSPIDER));
	}

	@Test
	public void excludesAllBrothersAndUnknownNpcs()
	{
		int[] brothers = {NpcID.BARROWS_AHRIM, NpcID.BARROWS_DHAROK, NpcID.BARROWS_GUTHAN, NpcID.BARROWS_KARIL, NpcID.BARROWS_TORAG, NpcID.BARROWS_VERAC};
		CryptKillCounts counts = new CryptKillCounts();
		for (int id : brothers)
		{
			Object npc = new Object();
			counts.damage(npc, id, REGION);
			assertFalse(counts.death(npc, REGION));
		}
		assertNull(CryptEnemy.forNpc(-1));
		assertEquals(0, counts.total());
	}

	@Test
	public void countsOnlyDamagedEnemyDeathsInCryptOnce()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		assertFalse(counts.death(new Object(), REGION));
		counts.damage(npc, NpcID.BARROWS_BLOODWORM, REGION);
		counts.damage(npc, NpcID.BARROWS_BLOODWORM, REGION);
		assertTrue(counts.death(npc, REGION));
		assertFalse(counts.death(npc, REGION));
		assertEquals(1, counts.count(CryptEnemy.BLOODWORM));
		assertEquals(1, counts.total());
	}

	@Test
	public void fatalHitsplatAfterDeathStillCountsOnlyOnce()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		assertFalse(counts.death(npc, REGION));
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		assertEquals(1, counts.total());
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		assertFalse(counts.death(npc, REGION));
		assertEquals(1, counts.total());
	}

	@Test
	public void rejectsDamageAndDeathsOutsideCrypt()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION + 1);
		assertFalse(counts.death(npc, REGION));
		npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		assertFalse(counts.death(npc, REGION + 1));
		assertEquals(0, counts.total());
	}

	@Test
	public void despawnAndSceneChangesNeverCountAsDeaths()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		counts.despawn(npc);
		assertFalse(counts.death(npc, REGION));
		npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		counts.clearActors();
		assertFalse(counts.death(npc, REGION));
		assertEquals(0, counts.total());
	}

	@Test
	public void rewardPotentialDecreaseResetsButIncreaseDoesNot()
	{
		CryptKillCounts counts = new CryptKillCounts();
		counts.potential(0);
		Object npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		counts.death(npc, REGION);
		counts.potential(10);
		counts.potential(10);
		assertEquals(1, counts.total());
		counts.clearActors();
		assertEquals(1, counts.total());
		counts.potential(0);
		assertEquals(0, counts.total());
	}

	@Test
	public void manualAndSessionResetClearCountsAndPendingDamage()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		counts.death(npc, REGION);
		counts.damage(new Object(), NpcID.BARROWS_RAT, REGION);
		counts.resetCounts();
		assertEquals(0, counts.total());
		counts.damage(npc, NpcID.BARROWS_RAT, REGION);
		counts.clearSession();
		assertFalse(counts.death(npc, REGION));
	}
}

package com.barrowscryptkilltracker;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CryptKillOverlayTest
{
	private CryptKillOverlay overlay(CryptKillCounts counts)
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		BarrowsCryptKillTrackerPlugin plugin = mock(BarrowsCryptKillTrackerPlugin.class);
		when(plugin.counts()).thenReturn(counts);
		when(plugin.inLowerCrypt()).thenReturn(true);
		CryptKillOverlay overlay = new CryptKillOverlay(client, plugin);
		overlay.setClearChildren(false);
		return overlay;
	}

	@Test
	public void usesSameLowPriorityAsBarrows()
	{
		assertEquals(0f, overlay(new CryptKillCounts()).getPriority(), 0f);
	}

	@Test
	public void rendersOnlyKilledTypesAndNoTotal()
	{
		CryptKillCounts counts = new CryptKillCounts();
		Object npc = new Object();
		counts.damage(npc, NpcID.BARROWS_BLOODWORM, CryptKillCounts.CRYPT_REGION);
		counts.death(npc, CryptKillCounts.CRYPT_REGION);
		CryptKillOverlay overlay = overlay(counts);
		Graphics2D graphics = new BufferedImage(300, 300, BufferedImage.TYPE_INT_ARGB).createGraphics();
		try { overlay.render(graphics); } finally { graphics.dispose(); }
		List<LayoutableRenderableEntity> children = overlay.getPanelComponent().getChildren();
		assertEquals("Only one nonzero monster row, no title or total", 1, children.size());
		assertTrue(children.get(0) instanceof LineComponent);
	}

	@Test
	public void hidesPanelOutsideLowerCryptEvenWithKills()
	{
		Client client = mock(Client.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		BarrowsCryptKillTrackerPlugin plugin = mock(BarrowsCryptKillTrackerPlugin.class);
		when(plugin.inLowerCrypt()).thenReturn(false);
		CryptKillOverlay overlay = new CryptKillOverlay(client, plugin);
		assertNull(overlay.render(null));
		assertTrue(overlay.getPanelComponent().getChildren().isEmpty());
	}

	@Test
	public void emptyCountsHidePanel()
	{
		CryptKillOverlay overlay = overlay(new CryptKillCounts());
		assertNull(overlay.render(null));
		assertTrue(overlay.getPanelComponent().getChildren().isEmpty());
	}
}

package com.barrowscryptkilltracker;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
