@RunWith(MockitoJUnitRunner.Silent.class)
public class LowerCryptVisibilityTest
{
	@Mock private Client client;
	@InjectMocks private BarrowsCryptKillTrackerPlugin plugin;
	private Scene scene;
	private WorldView view;

	@Before
	public void setup()
	{
		view = mock(WorldView.class);
		scene = mock(Scene.class);
		Player player = mock(Player.class);
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		when(client.getTopLevelWorldView()).thenReturn(view);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getLocalLocation()).thenReturn(new LocalPoint(64, 64));
		when(view.getScene()).thenReturn(scene);
		when(scene.getBaseX()).thenReturn(3550);
		when(scene.getBaseY()).thenReturn(9690);
	}

	@Test
	public void showsLowerMazeButNotBrotherTombsInSameRegion()
	{
		when(view.getPlane()).thenReturn(0);
		assertTrue(plugin.inLowerCrypt());
		when(view.getPlane()).thenReturn(3);
		assertFalse(plugin.inLowerCrypt());
	}

	@Test
	public void resolvesInstanceRegionButUsesLivePlane()
	{
		when(scene.isInstance()).thenReturn(true);
		int template = (3 << 24) | (440 << 14) | (1208 << 3);
		when(scene.getInstanceTemplateChunks()).thenReturn(new int[][][] {{{template}}});
		when(view.getPlane()).thenReturn(0);
		assertTrue(plugin.inLowerCrypt());
		when(view.getPlane()).thenReturn(3);
		assertFalse(plugin.inLowerCrypt());
	}

	@Test
	public void hidesOutsideRegionAndWhenLoggedOut()
	{
		when(scene.getBaseX()).thenReturn(3200);
		assertFalse(plugin.inLowerCrypt());
		when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
		assertFalse(plugin.inLowerCrypt());
	}
}

package com.barrowscryptkilltracker;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.OverlayManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.Silent.class)
public class PluginLifecycleTest
{
	@Mock private Client client;
	@Mock private ClientThread clientThread;
	@Mock private OverlayManager overlayManager;
	@Mock private CryptKillOverlay overlay;
	@InjectMocks private BarrowsCryptKillTrackerPlugin plugin;
	private NPC npc;

	@Before
	public void setup()
	{
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		doAnswer(invocation -> { ((Runnable) invocation.getArgument(0)).run(); return null; })
			.when(clientThread).invoke(any(Runnable.class));
		npc = mock(NPC.class);
		when(npc.getId()).thenReturn(NpcID.BARROWS_RAT);
		WorldView view = mock(WorldView.class);
		Scene scene = mock(Scene.class);
		when(npc.getWorldView()).thenReturn(view);
		when(view.getScene()).thenReturn(scene);
		when(scene.getBaseX()).thenReturn(3550);
		when(scene.getBaseY()).thenReturn(9690);
		when(npc.getLocalLocation()).thenReturn(new LocalPoint(64, 64));
		plugin.startUp();
	}

	private HitsplatApplied hit(boolean mine, int amount)
	{
		Hitsplat hitsplat = mock(Hitsplat.class);
		when(hitsplat.isMine()).thenReturn(mine);
		when(hitsplat.getAmount()).thenReturn(amount);
		HitsplatApplied event = new HitsplatApplied();
		event.setActor(npc);
		event.setHitsplat(hitsplat);
		return event;
	}

	@Test
	public void missingWorldViewDoesNotCrashDuringTransition()
	{
		when(npc.getWorldView()).thenReturn(null);
		plugin.onHitsplatApplied(hit(true, 5));
		plugin.onActorDeath(new ActorDeath(npc));
		assertEquals(0, plugin.counts().total());
	}

	@Test
	public void ignoresEventsAfterShutdownAndRemovesOverlay()
	{
		plugin.shutDown();
		plugin.onHitsplatApplied(hit(true, 5));
		plugin.onActorDeath(new ActorDeath(npc));
		assertEquals(0, plugin.counts().total());
		verify(overlayManager).add(overlay);
		verify(overlayManager).remove(overlay);
	}

	@Test
	public void onlyPersonalPositiveDamageCounts()
	{
		plugin.onHitsplatApplied(hit(false, 5));
		plugin.onHitsplatApplied(hit(true, 0));
		plugin.onActorDeath(new ActorDeath(npc));
		assertEquals(0, plugin.counts().total());
		plugin.onHitsplatApplied(hit(true, 5));
		assertEquals(1, plugin.counts().total());
		plugin.onActorDeath(new ActorDeath(npc));
		assertEquals(1, plugin.counts().total());
	}

	@Test
	public void despawnWithoutDeathAndShutdownDoNotCountKills()
	{
		plugin.onHitsplatApplied(hit(true, 5));
		plugin.onNpcDespawned(new NpcDespawned(npc));
		assertEquals(0, plugin.counts().total());
		plugin.onHitsplatApplied(hit(true, 5));
		plugin.onActorDeath(new ActorDeath(npc));
		assertEquals(1, plugin.counts().total());
		plugin.shutDown();
		assertEquals(0, plugin.counts().total());
	}
}
